package com.aac.ieojwo.alert.domain;
import com.aac.ieojwo.common.domain.BaseTimeEntity;import com.aac.ieojwo.user.domain.AacUser;import jakarta.persistence.*;import java.time.Instant;
@Entity @Table(name="alert_events",indexes=@Index(name="idx_alert_user_time",columnList="aac_user_id,occurred_at"))
public class AlertEvent extends BaseTimeEntity{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="aac_user_id",nullable=false)private AacUser user;@Enumerated(EnumType.STRING)@Column(nullable=false,length=30)private AlertType alertType;@Column(nullable=false,length=120)private String title;@Column(nullable=false,length=500)private String message;@Column(nullable=false)private Instant occurredAt;private Instant acknowledgedAt;protected AlertEvent(){}public static AlertEvent create(AacUser u,AlertType t,String title,String message){AlertEvent e=new AlertEvent();e.user=u;e.alertType=t;e.title=title;e.message=message;e.occurredAt=Instant.now();return e;}public void acknowledge(){acknowledgedAt=Instant.now();}public Long getId(){return id;}public AacUser getUser(){return user;}public AlertType getAlertType(){return alertType;}public String getTitle(){return title;}public String getMessage(){return message;}public Instant getOccurredAt(){return occurredAt;}public Instant getAcknowledgedAt(){return acknowledgedAt;}}
